-- Palace Fandom Atlas v1: additive, idempotent, no work-tag removal.
-- Existing member-created tags and story links are preserved.
CREATE TABLE IF NOT EXISTS public.fandom_directory (
 tag_id uuid PRIMARY KEY REFERENCES public.tags(id) ON DELETE CASCADE,
 media_categories text[] NOT NULL DEFAULT ARRAY['uncategorized']::text[],
 subcategory text NOT NULL DEFAULT '',
 aliases text[] NOT NULL DEFAULT ARRAY[]::text[],
 franchise text NOT NULL DEFAULT '',
 updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT fandom_directory_media_categories_check CHECK (
  cardinality(media_categories)>0
  AND media_categories <@ ARRAY['anime_manga','books_literature','cartoons_comics','celebrities_real_people','movies','music_bands','other_media','theater','tv_shows','video_games','uncategorized']::text[]
 )
);
CREATE INDEX IF NOT EXISTS fandom_directory_media_gin
 ON public.fandom_directory USING gin (media_categories);
CREATE INDEX IF NOT EXISTS fandom_directory_franchise_idx
 ON public.fandom_directory (lower(franchise));
ALTER TABLE public.fandom_directory ENABLE ROW LEVEL SECURITY;
DO $fandom_policy$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
  AND tablename='fandom_directory' AND policyname='public can browse registered fandoms') THEN
  CREATE POLICY "public can browse registered fandoms" ON public.fandom_directory
   FOR SELECT TO anon, authenticated
   USING (
    EXISTS (SELECT 1 FROM public.tags t WHERE t.id=tag_id
     AND t.category='fandom' AND t.status IN ('canonical','community'))
   );
 END IF;
END $fandom_policy$;
GRANT SELECT ON public.fandom_directory TO anon, authenticated;

