INSERT INTO public.tags(name,category,status)
SELECT seed.name,'fandom','canonical'
FROM seed
WHERE NOT EXISTS (
 SELECT 1 FROM public.tags t
 WHERE t.category='fandom' AND lower(t.name)=lower(seed.name)
)
ON CONFLICT DO NOTHING;

